export const KEY='atlas-duurzame-waarde-v1';
export const episodeIds=['climate','futures','energy','circular','value','nature','system','decision'];
export const fresh=()=>({version:1,started:false,episode:0,region:'coast',era:'now',player:{x:.37,y:.78},completed:[],flags:{},visits:[],concepts:[],tools:[],notes:{},trials:{},choices:{},settings:{motion:true,sound:false},models:{},connections:[]});
export function restore(raw){const s=fresh();if(raw?.version!==1)return s;s.started=raw.started===true;s.episode=Math.max(0,Math.min(7,Math.trunc(Number(raw.episode))||0));s.region=['coast','workshop','valley','glacier','mangrove'].includes(raw.region)?raw.region:'coast';s.era=['now','pressure','recovery'].includes(raw.era)&&s.region==='coast'?raw.era:'now';s.player=raw.player&&Number.isFinite(raw.player.x)&&Number.isFinite(raw.player.y)?{x:Math.max(.02,Math.min(.98,raw.player.x)),y:Math.max(.04,Math.min(.98,raw.player.y))}:s.player;for(const k of ['flags','notes','trials','choices','models'])if(raw[k]&&typeof raw[k]==='object'&&!Array.isArray(raw[k]))s[k]=raw[k];for(const k of ['completed','visits','concepts','tools'])s[k]=[...new Set(Array.isArray(raw[k])?raw[k].filter(v=>typeof v==='string'):[])];s.completed=s.completed.filter(v=>episodeIds.includes(v));s.settings={motion:raw.settings?.motion!==false,sound:raw.settings?.sound===true};s.connections=Array.isArray(raw.connections)?raw.connections.slice(0,100):[];return s;}
export const xp=s=>s.completed.length*150+s.concepts.length*15;
export const level=s=>Math.min(4,Math.floor(xp(s)/350)+1);
export function finish(s,id,ready){if(!ready)throw Error('Bekijk bij je opdracht welke stap nog ontbreekt.');if(!s.completed.includes(id))s.completed.push(id);return s;}
export const award=(s,id)=>{if(!s.concepts.includes(id))s.concepts.push(id);};
